using TeamsBot.Application; using TeamsBot.Domain;
namespace TeamsBot.Tests;
public class CompanionTests { [Fact] public async Task Approval_must_match_draft_version() { var d = new ActionItemDraft("a1", "Do X", "Details", null, null, AssignmentKind.Unassigned, null, .5, []); var a = new Approval("m", "a1", "u", "planner", MeetingCompanionService.VersionHash(d), DateTimeOffset.UtcNow); var s = new MeetingCompanionService(new T(), new I(), new P(), new B()); Assert.Equal("published", await s.PublishApprovedAsync(d, a, default)); } private sealed class T:ITranscriptSource{public Task<TranscriptArtifact?>GetAsync(MeetingRecord m,CancellationToken c)=>Task.FromResult<TranscriptArtifact?>(null);} private sealed class I:IInsightExtractor{public Task<InsightResult>ExtractAsync(TranscriptArtifact t,CancellationToken c)=>throw new NotImplementedException();} private sealed class P:ITaskPublisher{public Task<string>PublishAsync(ActionItemDraft d,Approval a,CancellationToken c)=>Task.FromResult("published");} private sealed class B:IMeetingPresence{public Task<string>JoinAsync(MeetingRecord m,CancellationToken c)=>Task.FromResult("joined");} }
